<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AnnouncementRepository,SettingsRepository};use App\Support\{Flash,SecureAttachment};
final class AnnouncementsController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function repo():AnnouncementRepository{return new AnnouncementRepository($this->app->database());}private function admin():?Response{return can('*')?null:Response::html('Forbidden',403);}
public function index(Request$r):Response{if($x=$this->admin())return$x;return$this->view('announcements/index',['pageTitle'=>'Announcements','pageDescription'=>'Publish announcements','activeMenu'=>'announcements','activeSubmenu'=>'','institute'=>(new SettingsRepository($this->app->database()))->institute(),'announcements'=>$this->repo()->all($this->i()),'teachers'=>(new \App\Repositories\EmployeeRepository($this->app->database()))->all($this->i(),'',true),'classes'=>$this->app->database()->query('SELECT id,name FROM classes WHERE institute_id=:i ORDER BY name',['i'=>$this->i()])->fetchAll(),'smsAvailable'=>can('sms.bulk_send')&&(new \App\Services\Sms\SmsSettings($this->app->database()))->get($this->i())['announcement_sms_enabled'],'scripts'=>['js/sms-center.js?v=1']]);}
public function store(Request$r):Response{if($x=$this->admin())return$x;try{$image=SecureAttachment::storeImage($r->file('image'),'announcements');$announcementId=$this->repo()->create($this->i(),['title'=>$r->input('title'),'message'=>$r->input('message'),'audience'=>$r->input('audience'),'image_path'=>$image,'show_popup'=>$r->input('show_popup'),'status'=>$r->input('status'),'publish_at'=>$r->input('publish_at'),'expires_at'=>$r->input('expires_at'),'teacher_id'=>(int)$r->input('teacher_id'),'class_id'=>(int)$r->input('class_id')],(int)user()['id']);Flash::add('success','Announcement published.');
// Optional SMS copy. The announcement is already saved, so an SMS problem is reported but never undoes it.
if($r->input('send_sms')&&$r->input('status')==='published'&&can('sms.bulk_send')){try{$sms=(new \App\Services\Sms\SmsAutomation($this->app->database()))->announcement($this->i(),$announcementId,(string)$r->input('title'),(string)$r->input('sms_audience','parents'),(string)$r->input('sms_text'),(int)$r->input('class_id')?:null,(string)$r->input('publish_at')?:null,(int)user()['id']);Flash::add('success',$sms['queued'].' announcement SMS queued for the SMS gateway'.($sms['skipped']?'; '.$sms['skipped'].' recipients had no usable phone number':'').'.');}catch(\DomainException$e){Flash::add('error','Announcement saved, but the SMS was not queued: '.$e->getMessage());}}
}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/announcements'));}
public function delete(Request$r):Response{if($x=$this->admin())return$x;$path=$this->repo()->delete($this->i(),(int)$r->route('id'));if($path&&is_file(BASE_PATH.'/'.$path))@unlink(BASE_PATH.'/'.$path);return Response::redirect(url('/admin/announcements'));}
}
